sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Removes existing alerts
    g_form.hideFieldMsg('u_on_behalf_of', true);

    //Get current user and date/time
    var caller = g_form.getValue('u_on_behalf_of');
    var created = g_form.getValue('opened_at');

    //Query AppointedPositions to determine if user is a Capstone user
    var capstone = new GlideAjax('x_g_dh5_appointed.appointedPosition');
    capstone.addParam('sysparm_name', 'appointedPosition');
    capstone.addParam('sysparm_user', caller);
    capstone.addParam('sysparm_created', created);
    capstone.getXMLAnswer(capstoneParse);


    //Parse the response
    function capstoneParse(response) {
        var obj = JSON.parse(response);

        //Display field message
        if (obj) {
			g_form.showFieldMsg("u_on_behalf_of", "Capstone/SES/Political Appointee; Preserve All Data", "warning");
        }

    }



}
